interactions.sample_code:
function insertionSort(A) {
  for (let j = 2; j <= 6; j++) {
    key(j);
    let i = j - 1;
    while (i >= 1 && compare(i, j)) {
      shift(i);
      i = i - 1;
    }
    markSorted(j);
  }
}

